// Shareable ESLint 9+ flat config for Library frontend projects.
// A consuming project's eslint.config.js should just be:
//
//   module.exports = require("@dltg/gulp-build/eslint-config");
//
// or, to layer project-specific overrides on top:
//
//   const base = require("@dltg/gulp-build/eslint-config");
//   module.exports = [...base, { rules: { /* overrides */ } }];
//
// eslint-config-airbnb-base does not ship a flat config yet
// (tracked upstream at airbnb/javascript#2961), so this bridges the
// old-style shareable config through @eslint/eslintrc's FlatCompat —
// the standard interim approach.

const { FlatCompat } = require("@eslint/eslintrc");
const js = require("@eslint/js");
const globals = require("globals");

const compat = new FlatCompat({
  baseDirectory: __dirname,
  recommendedConfig: js.configs.recommended,
});

module.exports = [
  {
    ignores: ["**/asset/css/**", "**/*.min.js", "**/*.min.css"],
  },

  ...compat.extends(
    "airbnb-base",
    "plugin:prettier/recommended",
    "plugin:yml/recommended",
  ),

  {
    languageOptions: {
      globals: {
        ...globals.browser,
        ...globals.node,
        // Drupal-project globals (originally "Copied from Drupal core")
        Drupal: true,
        drupalSettings: true,
        drupalTranslations: true,
        jQuery: true,
        _: true,
        Cookies: true,
        Backbone: true,
        Modernizr: true,
        loadjs: true,
        Shepherd: true,
        Sortable: true,
        once: true,
        CKEditor5: true,
        tabbable: true,
      },
    },
    rules: {
      "prettier/prettier": "error",
      "consistent-return": "off",
      "no-underscore-dangle": "off",
      "max-nested-callbacks": ["warn", 3],
      "import/no-mutable-exports": "warn",
      "no-plusplus": ["warn", { allowForLoopAfterthoughts: true }],
      "no-param-reassign": "off",
      "no-prototype-builtins": "off",
      "no-unused-vars": "warn",
      "operator-linebreak": [
        "error",
        "after",
        { overrides: { "?": "ignore", ":": "ignore" } },
      ],
      "yml/indent": ["error", 2],

      // Dropped: "valid-jsdoc" was removed from ESLint core in v9
      // (deprecated since v8). If JSDoc linting is still wanted, add
      // `eslint-plugin-jsdoc` and its rules separately.
    },
  },
];
